import { Router, Response } from 'express';
import { AuthenticatedRequest } from '../types.js';
import { getSupabaseClient, isRealSupabaseConfigured, mockDb } from '../services/supabase.js';

const router = Router({ mergeParams: true });

// GET /sites/:siteId/incidents - Fetch downtime incidents for site
router.get('/:siteId/incidents', async (req: AuthenticatedRequest, res: Response): Promise<void> => {
  try {
    const { siteId } = req.params;
    const userId = req.user!.id;

    if (isRealSupabaseConfigured()) {
      const supabase = getSupabaseClient();
      // Verify site belongs to user
      const { data: site, error: siteError } = await supabase
        .from('monitored_sites')
        .select('id')
        .eq('id', siteId)
        .eq('user_id', userId)
        .single();

      if (siteError || !site) {
        res.status(404).json({ error: 'Site not found or unauthorized' });
        return;
      }

      const { data: incidents, error: incidentsError } = await supabase
        .from('incidents')
        .select('*')
        .eq('site_id', siteId)
        .order('started_at', { ascending: false });

      if (incidentsError) {
        res.status(500).json({ error: incidentsError.message });
        return;
      }

      res.json(incidents || []);
      return;
    }

    // Mock DB fallback
    const site = mockDb.sites.find((s) => s.id === siteId && s.user_id === userId);
    if (!site) {
      res.status(404).json({ error: 'Site not found or unauthorized' });
      return;
    }

    const incidents = mockDb.incidents
      .filter((i) => i.site_id === siteId)
      .sort((a, b) => new Date(b.started_at).getTime() - new Date(a.started_at).getTime());

    res.json(incidents);
  } catch (err: any) {
    res.status(500).json({ error: err.message || 'Failed to fetch incidents' });
  }
});

export default router;
